import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import confetti from 'canvas-confetti';
import { useAuth } from '../context/AuthContext';
import KibaShield from '../components/KibaShield';
import Footer from '../components/Footer';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const demoAccounts = [
  { label: 'Administrator', color: '#EF233C', bg: '#FEE2E2', identifier: 'admin@kibalitest.com', password: 'Admin1234', char: '/images/char-yaga-idle.png' },
  { label: 'HR Staff', color: '#FFB703', bg: '#FFFBEB', identifier: 'staff@kibalitest.com', password: 'Staff1234', char: '/images/char-nanami-idle.png' },
  { label: 'Job Applicant', color: '#00B4D8', bg: '#E0F9FF', identifier: '0712345678', password: 'Customer1234', char: '/images/char-nobara-idle.png' }
];

const EyeIcon = ({ show }) => show ? (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
    <path d="M12 5C7 5 2.73 8.11 1 12.5C2.73 16.89 7 20 12 20C17 20 21.27 16.89 23 12.5C21.27 8.11 17 5 12 5Z" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <circle cx="12" cy="12.5" r="3.5" stroke="#00B4D8" strokeWidth="2"/>
    <circle cx="12" cy="12.5" r="1.5" fill="#00B4D8"/>
  </svg>
) : (
  <svg width="22" height="22" viewBox="0 0 24 24" fill="none">
    <path d="M2 2L22 22" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round"/>
    <path d="M6.71 6.71C4.56 8.08 2.9 10.11 2 12.5C3.73 16.89 8 20 13 20C15.11 20 17.07 19.32 18.66 18.18" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.88 4.13C10.57 4.05 11.28 4 12 4C17 4 21.27 7.11 23 11.5" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
    <path d="M9.76 9.76C9.29 10.23 9 10.88 9 11.6C9 13.14 10.35 14.4 12 14.4C12.76 14.4 13.45 14.12 13.96 13.66" stroke="#00B4D8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
  </svg>
);

const Login = () => {
  const { login, darkMode } = useAuth();
  const navigate = useNavigate();
  const [identifier, setIdentifier] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const [pose, setPose] = useState(1);
  const [shieldState, setShieldState] = useState('idle');
  const [showDemo, setShowDemo] = useState(false);
  const [selectedDemo, setSelectedDemo] = useState(null);

  useEffect(() => {
    const remembered = localStorage.getItem('kibaliRememberMe');
    if (remembered) { setIdentifier(remembered); setRememberMe(true); setPose(8); }
  }, []);

  const handleDemoSelect = (account) => {
    setIdentifier(account.identifier);
    setPassword(account.password);
    setSelectedDemo(account);
    setShowDemo(false);
    setPose(8);
    setShieldState('idle');
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (!identifier || !password) {
      setError('Please fill in all fields');
      setPose(3); setShieldState('warning');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
      return;
    }
    setLoading(true); setPose(7); setShieldState('idle');
    try {
      const res = await axios.post(`${API}/api/auth/login`, { identifier, password });
      setPose(2); setShieldState('success');
      confetti({ particleCount: 140, spread: 80, origin: { y: 0.6 }, colors: ['#06D6A0', '#00B4D8', '#FF6B35'] });
      if (rememberMe) localStorage.setItem('kibaliRememberMe', identifier);
      else localStorage.removeItem('kibaliRememberMe');
      setTimeout(() => {
        login(res.data.user, res.data.token);
        const role = res.data.user.role;
        navigate(role === 'admin' ? '/admin' : role === 'staff' ? '/staff' : '/dashboard');
      }, 1500);
    } catch (err) {
      setError(err.response?.data?.message || 'Something went wrong. Please try again.');
      setPose(4); setShieldState('danger');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
    } finally { setLoading(false); }
  };

  const inputStyle = {
    width: '100%', padding: '14px 16px', border: '2px solid #E0F2FE', borderRadius: '12px',
    fontSize: '15px', fontFamily: 'Inter, sans-serif',
    background: darkMode ? '#0F172A' : '#F0F9FF',
    color: darkMode ? '#F1F5F9' : '#0F172A',
    outline: 'none', boxSizing: 'border-box', transition: 'border-color 0.2s'
  };

  const sideChar = selectedDemo ? selectedDemo.char : '/images/char-loid-idle.png';

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: darkMode ? '#0F172A' : '#F0F9FF' }}>
      <div style={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', padding: '32px 16px' }}>
        <div style={{ display: 'flex', gap: '48px', alignItems: 'center', width: '100%', maxWidth: '960px', flexWrap: 'wrap', justifyContent: 'center' }}>

          <div className="animate-slideInLeft" style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '24px' }}>
            <div style={{ position: 'relative', display: 'flex', alignItems: 'flex-end', gap: '16px' }}>
              <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center', gap: '8px' }}>
                <img src={sideChar} alt="" className="animate-float" style={{ width: '110px', height: '150px', objectFit: 'contain', filter: 'drop-shadow(0 8px 20px rgba(0,0,0,0.2))' }}
                  onError={e => e.target.style.display = 'none'} />
                {selectedDemo && (
                  <div className="animate-bubblePop" style={{ background: '#fff', border: `2px solid ${selectedDemo.color}`, borderRadius: '12px', padding: '8px 12px', fontSize: '11px', fontWeight: 700, color: selectedDemo.color, textAlign: 'center', maxWidth: '120px' }}>
                    {selectedDemo.label} ready!
                  </div>
                )}
              </div>
              <KibaShield pose={pose} shieldState={shieldState} customLabel={loading ? 'Verifying securely...' : null} />
            </div>
            <div style={{ textAlign: 'center' }}>
              <h1 style={{ fontSize: '28px', fontWeight: 900, color: darkMode ? '#F1F5F9' : '#0F172A', margin: 0, letterSpacing: '-0.5px' }}>KibaliGuard</h1>
              <p style={{ color: '#64748B', fontSize: '14px', marginTop: '4px' }}>Your data. Your rules. Your control.</p>
            </div>
          </div>

          <div className="animate-slideInRight" style={{ background: darkMode ? '#1E293B' : '#ffffff', borderRadius: '24px', padding: '44px 40px', boxShadow: '0 8px 48px rgba(0,0,0,0.1)', width: '100%', maxWidth: '420px', border: '1.5px solid #E0F2FE' }}>
            <h2 style={{ fontSize: '28px', fontWeight: 900, color: darkMode ? '#F1F5F9' : '#0F172A', marginBottom: '6px', letterSpacing: '-0.5px' }}>Welcome back</h2>
            <p style={{ color: '#64748B', fontSize: '14px', marginBottom: '28px' }}>Sign in to your KibaliGuard account</p>

            {error && (
              <div className="animate-slideUp" style={{ background: '#FEF2F2', color: '#EF233C', border: '1.5px solid #FECACA', borderRadius: '12px', padding: '13px 16px', fontSize: '14px', marginBottom: '20px' }}>
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit}>
              <div style={{ marginBottom: '20px' }}>
                <label style={{ display: 'block', fontWeight: 700, fontSize: '13px', color: darkMode ? '#CBD5E1' : '#0F172A', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                  Email or phone number
                </label>
                <input type="text" placeholder="e.g. your@gmail.com or 07XXXXXXXX" value={identifier}
                  onChange={e => { setIdentifier(e.target.value); if (e.target.value.length > 0) setPose(8); else setPose(1); }}
                  style={inputStyle}
                  onFocus={e => e.target.style.borderColor = '#00B4D8'}
                  onBlur={e => e.target.style.borderColor = '#E0F2FE'}
                />
              </div>

              <div style={{ marginBottom: '16px' }}>
                <label style={{ display: 'block', fontWeight: 700, fontSize: '13px', color: darkMode ? '#CBD5E1' : '#0F172A', marginBottom: '8px', textTransform: 'uppercase', letterSpacing: '0.5px' }}>
                  Password
                </label>
                <div style={{ position: 'relative' }}>
                  <input type={showPassword ? 'text' : 'password'} placeholder="Enter your password" value={password}
                    onChange={e => setPassword(e.target.value)}
                    onFocus={() => { setPose(9); setShieldState('idle'); }}
                    onBlur={() => { if (identifier.length > 0) setPose(8); else setPose(1); }}
                    style={{ ...inputStyle, paddingRight: '48px' }}
                  />
                  <button type="button" onClick={() => setShowPassword(p => !p)}
                    style={{ position: 'absolute', right: '12px', top: '50%', transform: 'translateY(-50%)', background: 'none', border: 'none', cursor: 'pointer', padding: '4px', display: 'flex' }}>
                    <EyeIcon show={showPassword} />
                  </button>
                </div>
              </div>

              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '28px', flexWrap: 'wrap', gap: '8px' }}>
                <label style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer' }}>
                  <input type="checkbox" checked={rememberMe} onChange={e => setRememberMe(e.target.checked)} style={{ width: '16px', height: '16px', accentColor: '#00B4D8', cursor: 'pointer' }} />
                  <span style={{ fontSize: '14px', color: '#64748B', fontWeight: 500 }}>Remember me</span>
                </label>
                <Link to="/forgot-password" style={{ color: '#00B4D8', fontSize: '14px', textDecoration: 'none', fontWeight: 700 }}>Forgot password?</Link>
              </div>

              <button type="submit" disabled={loading} style={{ width: '100%', padding: '15px', background: loading ? '#00B4D8' : '#FF6B35', color: '#fff', border: 'none', borderRadius: '14px', fontWeight: 800, fontSize: '16px', cursor: loading ? 'not-allowed' : 'pointer', fontFamily: 'Inter, sans-serif', marginBottom: '20px', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '10px', boxShadow: '0 8px 24px rgba(255,107,53,0.35)', transition: 'all 0.2s' }}>
                {loading ? (
                  <>
                    <span style={{ width: '18px', height: '18px', border: '3px solid rgba(255,255,255,0.3)', borderTop: '3px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'kibashield-spin 0.8s linear infinite' }} />
                    Signing you in...
                  </>
                ) : 'Sign In'}
              </button>
            </form>

            <div style={{ borderTop: `1px solid ${darkMode ? '#334155' : '#E0F2FE'}`, paddingTop: '16px', marginBottom: '16px', position: 'relative' }}>
              <button type="button" onClick={() => setShowDemo(!showDemo)}
                style={{ width: '100%', padding: '11px 16px', background: darkMode ? '#0F172A' : '#F0F9FF', border: `1.5px solid ${darkMode ? '#334155' : '#DBEAFE'}`, borderRadius: '12px', fontWeight: 600, fontSize: '13px', color: '#64748B', cursor: 'pointer', fontFamily: 'Inter, sans-serif', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                <span>🎮 Try a demo account</span>
                <span style={{ fontSize: '16px', transform: showDemo ? 'rotate(180deg)' : 'rotate(0)', transition: 'transform 0.2s' }}>▾</span>
              </button>

              {showDemo && (
                <div className="animate-slideUp" style={{ position: 'absolute', bottom: '100%', left: 0, right: 0, background: darkMode ? '#1E293B' : '#fff', border: `1.5px solid ${darkMode ? '#334155' : '#DBEAFE'}`, borderRadius: '16px', padding: '10px', marginBottom: '6px', boxShadow: '0 8px 32px rgba(0,0,0,0.15)', zIndex: 10 }}>
                  <p style={{ fontSize: '11px', color: '#94A3B8', fontWeight: 700, textTransform: 'uppercase', letterSpacing: '0.5px', padding: '4px 8px 8px', margin: 0 }}>Select account type to auto-fill</p>
                  {demoAccounts.map(account => (
                    <button key={account.label} type="button" onClick={() => handleDemoSelect(account)}
                      style={{ width: '100%', padding: '10px 12px', background: 'transparent', border: 'none', borderRadius: '10px', cursor: 'pointer', fontFamily: 'Inter, sans-serif', display: 'flex', alignItems: 'center', gap: '12px', textAlign: 'left', transition: 'background 0.15s' }}
                      onMouseEnter={e => e.currentTarget.style.background = darkMode ? '#0F172A' : '#F0F9FF'}
                      onMouseLeave={e => e.currentTarget.style.background = 'transparent'}>
                      <div style={{ width: '40px', height: '40px', borderRadius: '10px', background: account.bg, display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
                        <img src={account.char} alt="" style={{ width: '32px', height: '36px', objectFit: 'contain' }} onError={e => { e.target.style.display = 'none'; e.target.parentNode.innerHTML = `<span style="font-size:18px;font-weight:800;color:${account.color}">${account.label.charAt(0)}</span>`; }} />
                      </div>
                      <div style={{ flex: 1 }}>
                        <p style={{ fontWeight: 800, fontSize: '13px', color: darkMode ? '#F1F5F9' : '#0F172A', margin: 0 }}>{account.label}</p>
                        <p style={{ fontSize: '11px', color: '#94A3B8', margin: '2px 0 0', fontFamily: 'Roboto Mono, monospace' }}>{account.identifier}</p>
                      </div>
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                        <polyline points="9 18 15 12 9 6" stroke="#94A3B8" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"/>
                      </svg>
                    </button>
                  ))}
                </div>
              )}
            </div>

            <div style={{ textAlign: 'center', fontSize: '14px', color: '#64748B' }}>
              No account yet?{' '}
              <Link to="/register" style={{ color: '#FF6B35', fontWeight: 800, textDecoration: 'none' }}>Register here</Link>
            </div>
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default Login;
